def required_capacity(bookings: list[list[int]]) -> int:
    # Define a helper class to represent an event on the sweep line
    class Event:
        def __init__(self, x, y):
            self.x = x  # Time point
            self.y = y  # Type of event (0 for start, 1 for end)

    events = []
    for start, end in bookings:
        events.append(Event(start, 0))  # Start of an interval
        events.append(Event(end, 1))   # End of an interval

    # Sort the events by their time points
    events.sort(key=lambda event: event.x)

    active_count = 0
    max_active_count = 0

    for event in events:
        if event.y == 0:
            active_count += 1
        else:
            active_count -= 1

        max_active_count = max(max_active_count, active_count)

    return max_active_count

import heapq

def required_capacity(bookings: list[list[int]]) -> int:
    active_bookings = []
    max_active_bookings = 0

    for start, end in sorted(bookings):
        while active_bookings and active_bookings[0][0] < start:
            heapq.heappop(active_bookings)

        heapq.heappush(active_bookings, (end, start))
        max_active_bookings = max(max_active_bookings, len(active_bookings))

    return max_active_bookings

